-- StudioDesk - complete PostgreSQL schema (generated by tools/build_schema.py from migrations/*.sql).
-- Do not edit by hand: add the next migrations/NNN_name.sql and rebuild.
--
-- Create a database by hand (the API does this itself when it starts, so this is optional):
--   psql "$PG_DSN" -v ON_ERROR_STOP=1 -c 'CREATE SCHEMA spa' -c 'SET search_path TO spa' -f sql/schema.sql
-- It also records the migrations as applied, so the API will not try to run them again.
-- Needs the btree_gist extension (bundled with PostgreSQL; creating it needs the database owner).
-- Column-by-column documentation: docs/schema.md

-- ======== 001_init.sql ========
-- Spa Manager schema. Applied once by app/migrate.py inside the configured schema (default "spa").
-- Needed so the database itself can refuse a therapist being booked twice at the same time.
CREATE EXTENSION IF NOT EXISTS btree_gist;

CREATE TABLE users (
  id            BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  username      TEXT NOT NULL CHECK (length(btrim(username)) >= 3),
  password_hash TEXT NOT NULL,
  role          TEXT NOT NULL DEFAULT 'staff' CHECK (role IN ('admin', 'staff')),
  is_active     BOOLEAN NOT NULL DEFAULT TRUE,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX users_username_key ON users (lower(username));

-- Opaque bearer tokens: only the SHA-256 fingerprint is stored.
CREATE TABLE sessions (
  token_hash TEXT PRIMARY KEY,
  user_id    BIGINT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at TIMESTAMPTZ NOT NULL
);
CREATE INDEX sessions_user_idx ON sessions (user_id);
CREATE INDEX sessions_expires_idx ON sessions (expires_at);

CREATE TABLE customers (
  id         BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  name       TEXT NOT NULL CHECK (length(btrim(name)) > 0),
  phone      TEXT NOT NULL CONSTRAINT customers_phone_key UNIQUE,
  email      TEXT,
  gender     TEXT,
  dob        DATE,
  address    TEXT,
  notes      TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX customers_name_idx ON customers (lower(name));

CREATE TABLE therapists (
  id                BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  name              TEXT NOT NULL CHECK (length(btrim(name)) > 0),
  phone             TEXT,
  fixed_salary      NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK (fixed_salary >= 0),
  incentive_percent NUMERIC(5,2)  NOT NULL DEFAULT 0 CHECK (incentive_percent BETWEEN 0 AND 100),
  is_active         BOOLEAN NOT NULL DEFAULT TRUE,
  joined_on         DATE,
  created_at        TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE services (
  id           BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  name         TEXT NOT NULL CHECK (length(btrim(name)) > 0),
  price        NUMERIC(12,2) NOT NULL CHECK (price >= 0),
  duration_min INTEGER NOT NULL DEFAULT 60 CHECK (duration_min > 0),
  is_active    BOOLEAN NOT NULL DEFAULT TRUE
);
CREATE UNIQUE INDEX services_name_key ON services (lower(name));

-- start_at is the spa's local wall-clock time (no zone). price is the amount agreed at booking
-- (a later change to the service's list price never touches it); payroll is computed from it.
CREATE TABLE appointments (
  id           BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  customer_id  BIGINT NOT NULL REFERENCES customers  (id),
  therapist_id BIGINT NOT NULL REFERENCES therapists (id),
  service_id   BIGINT NOT NULL REFERENCES services   (id),
  start_at     TIMESTAMP NOT NULL,
  duration_min INTEGER NOT NULL CHECK (duration_min > 0),
  end_at       TIMESTAMP GENERATED ALWAYS AS (start_at + make_interval(mins => duration_min)) STORED,
  price        NUMERIC(12,2) NOT NULL CHECK (price >= 0),
  status       TEXT NOT NULL DEFAULT 'booked' CHECK (status IN ('booked', 'completed', 'cancelled', 'no_show')),
  notes        TEXT,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  -- one therapist cannot have two live appointments that overlap (back-to-back is fine)
  CONSTRAINT appointments_no_overlap
    EXCLUDE USING gist (therapist_id WITH =, tsrange(start_at, end_at) WITH &&)
    WHERE (status IN ('booked', 'completed'))
);
CREATE INDEX appointments_start_idx     ON appointments (start_at);
CREATE INDEX appointments_therapist_idx ON appointments (therapist_id, start_at);
CREATE INDEX appointments_customer_idx  ON appointments (customer_id, start_at DESC);

-- ======== 002_comments.sql ========
-- Descriptions stored in the database itself (visible in psql \d+, pgAdmin, DBeaver) and used to build docs/schema.md.
COMMENT ON TABLE users IS 'Staff logins. Role admin = everything; staff = customers, onboarding, appointments.';
COMMENT ON COLUMN users.username IS 'Login name, at least 3 characters; unique ignoring case (users_username_key).';
COMMENT ON COLUMN users.password_hash IS 'PBKDF2-SHA256 hash "pbkdf2$iterations$salt$hash"; the password itself is never stored.';
COMMENT ON COLUMN users.role IS 'admin or staff.';
COMMENT ON COLUMN users.is_active IS 'False blocks login and ends all sessions immediately; accounts are deactivated, never deleted.';

COMMENT ON TABLE sessions IS 'Login sessions as opaque bearer tokens. Only the SHA-256 fingerprint of a token is stored, so a database leak cannot be replayed.';
COMMENT ON COLUMN sessions.token_hash IS 'SHA-256 hex of the token handed to the browser.';
COMMENT ON COLUMN sessions.expires_at IS 'Sessions last 12 hours; expired rows are swept at the next login.';

COMMENT ON TABLE customers IS 'Spa clients, created by onboarding or by hand.';
COMMENT ON COLUMN customers.phone IS 'Unique across customers (customers_phone_key); how reception finds a returning client.';
COMMENT ON COLUMN customers.gender IS 'Free text; the UI offers Female, Male, Other.';
COMMENT ON COLUMN customers.dob IS 'Date of birth (optional).';
COMMENT ON COLUMN customers.notes IS 'Allergies, skin type, preferences.';

COMMENT ON TABLE therapists IS 'Staff who perform services and are paid on payslips. Never deleted, only set inactive, so past payslips stay reproducible.';
COMMENT ON COLUMN therapists.fixed_salary IS 'Monthly fixed pay in INR; the base of every payslip.';
COMMENT ON COLUMN therapists.incentive_percent IS 'Percent (0-100) of the price of the therapist''s completed appointments in a month paid on top of the salary.';
COMMENT ON COLUMN therapists.is_active IS 'Inactive therapists cannot be booked and drop out of the monthly payroll list.';

COMMENT ON TABLE services IS 'Price list of treatments. Editing a price affects future bookings only.';
COMMENT ON COLUMN services.price IS 'List price in INR, copied onto an appointment when it is booked.';
COMMENT ON COLUMN services.duration_min IS 'Minutes a booking blocks on the therapist''s calendar.';
COMMENT ON COLUMN services.is_active IS 'Inactive services cannot be booked; history keeps pointing at them.';

COMMENT ON TABLE appointments IS 'One booking of one customer with one therapist for one service. Completed appointments drive revenue and incentive.';
COMMENT ON COLUMN appointments.start_at IS 'Spa-local wall-clock time (no time zone).';
COMMENT ON COLUMN appointments.duration_min IS 'Copied from the service at booking time.';
COMMENT ON COLUMN appointments.end_at IS 'Generated: start_at + duration_min. Used by the no-overlap constraint.';
COMMENT ON COLUMN appointments.price IS 'Amount agreed at booking in INR (list price unless overridden). Frozen: later price edits never change it. Payroll uses this.';
COMMENT ON COLUMN appointments.status IS 'booked -> completed | cancelled | no_show. Only completed counts for revenue and incentive; only booked can be edited.';
COMMENT ON CONSTRAINT appointments_no_overlap ON appointments IS 'A therapist cannot have two booked/completed appointments whose time ranges overlap (back-to-back is allowed). Enforced by the database so concurrent requests cannot double-book.';

-- Remaining columns (tests/test_schema_files.py fails if any table or column is left undocumented).
COMMENT ON COLUMN users.id IS 'Surrogate key.';
COMMENT ON COLUMN users.created_at IS 'When the account was created.';
COMMENT ON COLUMN sessions.user_id IS 'Owner of the session; deleting the user deletes their sessions.';
COMMENT ON COLUMN sessions.created_at IS 'When the user signed in.';
COMMENT ON COLUMN customers.id IS 'Surrogate key.';
COMMENT ON COLUMN customers.name IS 'Full name; must not be blank.';
COMMENT ON COLUMN customers.email IS 'Optional contact email.';
COMMENT ON COLUMN customers.address IS 'Optional postal address.';
COMMENT ON COLUMN customers.created_at IS 'Onboarding time; the "new customers" report counts by it in the spa time zone.';
COMMENT ON COLUMN customers.updated_at IS 'Last edit.';
COMMENT ON COLUMN therapists.id IS 'Surrogate key.';
COMMENT ON COLUMN therapists.name IS 'Name shown on bookings and printed on the payslip.';
COMMENT ON COLUMN therapists.phone IS 'Optional contact number.';
COMMENT ON COLUMN therapists.joined_on IS 'Optional joining date.';
COMMENT ON COLUMN therapists.created_at IS 'When the record was added.';
COMMENT ON COLUMN services.id IS 'Surrogate key.';
COMMENT ON COLUMN services.name IS 'Treatment name; unique ignoring case (services_name_key).';
COMMENT ON COLUMN appointments.id IS 'Surrogate key.';
COMMENT ON COLUMN appointments.customer_id IS 'Who is being treated. Customers are never deleted, so history stays intact.';
COMMENT ON COLUMN appointments.therapist_id IS 'Who performs it; also the key of the no-overlap constraint.';
COMMENT ON COLUMN appointments.service_id IS 'What is performed.';
COMMENT ON COLUMN appointments.notes IS 'Free-text note for this visit.';
COMMENT ON COLUMN appointments.created_at IS 'When it was booked.';
COMMENT ON COLUMN appointments.updated_at IS 'Last reschedule or status change.';

-- ======== 003_therapist_bonuses.sql ========
-- Extra incentives paid to a therapist on a given day (festival bonus, extra hours, a tip passed on, ...),
-- on top of the percentage incentive. They land on the payslip of the month of on_date.
CREATE TABLE therapist_bonuses (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  therapist_id BIGINT NOT NULL REFERENCES therapists (id),
  on_date DATE NOT NULL,
  amount NUMERIC(12,2) NOT NULL CHECK (amount > 0),
  note TEXT,
  appointment_id BIGINT REFERENCES appointments (id),
  created_by BIGINT REFERENCES users (id),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX therapist_bonuses_therapist_idx ON therapist_bonuses (therapist_id, on_date);

COMMENT ON TABLE therapist_bonuses IS 'Extra incentives for a therapist on a date, added to that month''s payslip on top of the percentage incentive.';
COMMENT ON COLUMN therapist_bonuses.id IS 'Identity.';
COMMENT ON COLUMN therapist_bonuses.therapist_id IS 'Who gets it.';
COMMENT ON COLUMN therapist_bonuses.created_at IS 'When it was added.';
COMMENT ON COLUMN therapist_bonuses.on_date IS 'The day the incentive is for; decides which month''s payslip it is on.';
COMMENT ON COLUMN therapist_bonuses.amount IS 'INR, more than 0.';
COMMENT ON COLUMN therapist_bonuses.note IS 'Why, e.g. Festival bonus, Extra hours.';
COMMENT ON COLUMN therapist_bonuses.appointment_id IS 'The appointment it was given for, when it was given from the appointments list (optional).';
COMMENT ON COLUMN therapist_bonuses.created_by IS 'The user who added it.';

-- ======== 004_spas.sql ========
-- Many spas in one system. Every business row belongs to exactly one spa; admins and staff belong to one
-- spa and see only its data; a superadmin belongs to none and can open any spa. Existing data becomes spa 1.
CREATE TABLE spas (
  id         BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  name       TEXT NOT NULL CHECK (length(btrim(name)) > 0),
  is_active  BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX spas_name_key ON spas (lower(name));
INSERT INTO spas (name) OVERRIDING SYSTEM VALUE SELECT 'My Spa';

-- users: superadmin has no spa; admin and staff have exactly one
ALTER TABLE users ADD COLUMN spa_id BIGINT REFERENCES spas (id);
UPDATE users SET spa_id = (SELECT min(id) FROM spas);
ALTER TABLE users DROP CONSTRAINT users_role_check;
ALTER TABLE users ADD CONSTRAINT users_role_check CHECK (role IN ('superadmin', 'admin', 'staff'));
ALTER TABLE users ADD CONSTRAINT users_spa_by_role CHECK ((role = 'superadmin') = (spa_id IS NULL));
CREATE INDEX users_spa_idx ON users (spa_id);

-- every business table gets its spa
ALTER TABLE customers ADD COLUMN spa_id BIGINT REFERENCES spas (id);
ALTER TABLE therapists ADD COLUMN spa_id BIGINT REFERENCES spas (id);
ALTER TABLE services ADD COLUMN spa_id BIGINT REFERENCES spas (id);
ALTER TABLE appointments ADD COLUMN spa_id BIGINT REFERENCES spas (id);
ALTER TABLE therapist_bonuses ADD COLUMN spa_id BIGINT REFERENCES spas (id);
UPDATE customers SET spa_id = (SELECT min(id) FROM spas);
UPDATE therapists SET spa_id = (SELECT min(id) FROM spas);
UPDATE services SET spa_id = (SELECT min(id) FROM spas);
UPDATE appointments SET spa_id = (SELECT min(id) FROM spas);
UPDATE therapist_bonuses SET spa_id = (SELECT min(id) FROM spas);
ALTER TABLE customers ALTER COLUMN spa_id SET NOT NULL;
ALTER TABLE therapists ALTER COLUMN spa_id SET NOT NULL;
ALTER TABLE services ALTER COLUMN spa_id SET NOT NULL;
ALTER TABLE appointments ALTER COLUMN spa_id SET NOT NULL;
ALTER TABLE therapist_bonuses ALTER COLUMN spa_id SET NOT NULL;

-- phone numbers and service names are unique within a spa, not across spas
ALTER TABLE customers DROP CONSTRAINT customers_phone_key;
ALTER TABLE customers ADD CONSTRAINT customers_phone_key UNIQUE (spa_id, phone);
DROP INDEX services_name_key;
CREATE UNIQUE INDEX services_name_key ON services (spa_id, lower(name));

CREATE INDEX customers_spa_idx ON customers (spa_id, lower(name));
CREATE INDEX therapists_spa_idx ON therapists (spa_id);
CREATE INDEX appointments_spa_start_idx ON appointments (spa_id, start_at);
CREATE INDEX therapist_bonuses_spa_idx ON therapist_bonuses (spa_id, on_date);

COMMENT ON TABLE spas IS 'Each spa (business) using the system. Its admins and staff see only its data; a superadmin sees every spa.';
COMMENT ON COLUMN spas.id IS 'Identity.';
COMMENT ON COLUMN spas.name IS 'Business name, shown in the app and on payslips and reports; unique ignoring case.';
COMMENT ON COLUMN spas.is_active IS 'False stops every login of this spa at once (superadmin only); data is kept.';
COMMENT ON COLUMN spas.created_at IS 'When the spa was added.';
COMMENT ON COLUMN users.spa_id IS 'The spa an admin or staff login belongs to; NULL for a superadmin (users_spa_by_role).';
COMMENT ON COLUMN customers.spa_id IS 'The spa this customer belongs to; phone is unique within it (customers_phone_key).';
COMMENT ON COLUMN therapists.spa_id IS 'The spa this therapist works for.';
COMMENT ON COLUMN services.spa_id IS 'The spa offering this service; name is unique within it.';
COMMENT ON COLUMN appointments.spa_id IS 'The spa of the booking; always that of its customer, therapist and service.';
COMMENT ON COLUMN therapist_bonuses.spa_id IS 'The spa of the therapist.';
COMMENT ON COLUMN users.role IS 'superadmin (every spa, creates spas and their admins), admin (one spa, creates its staff) or staff.';

