-- ======== 006_customer_plans.sql ========
-- Prepaid customer plans: one balance is either hours or INR, never both.
CREATE TABLE customer_plans (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  customer_id BIGINT NOT NULL REFERENCES customers(id),
  spa_id BIGINT NOT NULL REFERENCES spas(id),
  name TEXT NOT NULL CHECK (length(btrim(name)) > 0),
  plan_type TEXT NOT NULL CHECK (plan_type IN ('hours', 'rupees')),
  purchased_amount NUMERIC(12,2) NOT NULL CHECK (purchased_amount > 0),
  balance NUMERIC(12,2) NOT NULL CHECK (balance >= 0 AND balance <= purchased_amount),
  expires_on DATE,
  notes TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX customer_plans_customer_idx ON customer_plans (spa_id, customer_id, created_at);

CREATE TABLE plan_redemptions (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  plan_id BIGINT NOT NULL REFERENCES customer_plans(id),
  appointment_id BIGINT NOT NULL REFERENCES appointments(id),
  spa_id BIGINT NOT NULL REFERENCES spas(id),
  amount NUMERIC(12,2) NOT NULL CHECK (amount > 0),
  unit TEXT NOT NULL CHECK (unit IN ('hours', 'rupees')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  reversed_at TIMESTAMPTZ
);
CREATE UNIQUE INDEX plan_redemptions_one_active_appointment
  ON plan_redemptions (appointment_id) WHERE reversed_at IS NULL;
CREATE INDEX plan_redemptions_plan_idx ON plan_redemptions (plan_id, created_at);

COMMENT ON TABLE customer_plans IS 'Prepaid package owned by one customer in one spa. A balance is measured in hours or INR.';
COMMENT ON COLUMN customer_plans.id IS 'Identity.';
COMMENT ON COLUMN customer_plans.customer_id IS 'Customer who purchased this plan.';
COMMENT ON COLUMN customer_plans.spa_id IS 'Owning spa; must match the customer and appointment.';
COMMENT ON COLUMN customer_plans.name IS 'Display name of the prepaid package.';
COMMENT ON COLUMN customer_plans.plan_type IS 'Balance unit: hours for service time, or rupees for service value.';
COMMENT ON COLUMN customer_plans.purchased_amount IS 'Original amount purchased, in the plan unit.';
COMMENT ON COLUMN customer_plans.balance IS 'Remaining amount, in the plan unit; reduced only when an appointment is completed.';
COMMENT ON COLUMN customer_plans.expires_on IS 'Optional last date on which this plan can be redeemed.';
COMMENT ON COLUMN customer_plans.notes IS 'Optional purchase or package notes.';
COMMENT ON COLUMN customer_plans.created_at IS 'When the plan was added to the customer.';

COMMENT ON TABLE plan_redemptions IS 'Auditable deductions from prepaid customer plans for completed appointments; reversal restores the balance.';
COMMENT ON COLUMN plan_redemptions.id IS 'Identity.';
COMMENT ON COLUMN plan_redemptions.plan_id IS 'The prepaid plan that paid for the appointment.';
COMMENT ON COLUMN plan_redemptions.appointment_id IS 'The completed appointment; only one active plan deduction per appointment.';
COMMENT ON COLUMN plan_redemptions.spa_id IS 'Owning spa for tenant isolation.';
COMMENT ON COLUMN plan_redemptions.amount IS 'Amount deducted in the unit recorded alongside it.';
COMMENT ON COLUMN plan_redemptions.unit IS 'hours or rupees, matching the plan type.';
COMMENT ON COLUMN plan_redemptions.created_at IS 'When the appointment consumed the plan.';
COMMENT ON COLUMN plan_redemptions.reversed_at IS 'When a deduction was reversed because the appointment left completed status.';

-- ======== 007_therapist_shifts.sql ========
-- Reusable shift templates and a therapist's weekly shift assignment.
-- day_of_week uses ISO numbering: Monday=0 through Sunday=6.
CREATE TABLE shifts (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  spa_id BIGINT NOT NULL REFERENCES spas(id),
  name TEXT NOT NULL CHECK (length(btrim(name)) > 0),
  start_time TIME NOT NULL,
  end_time TIME NOT NULL,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK (start_time < end_time)
);
CREATE UNIQUE INDEX shifts_spa_name_idx ON shifts (spa_id, lower(name));

CREATE TABLE therapist_shift_assignments (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  spa_id BIGINT NOT NULL REFERENCES spas(id),
  therapist_id BIGINT NOT NULL REFERENCES therapists(id),
  shift_id BIGINT NOT NULL REFERENCES shifts(id),
  day_of_week SMALLINT NOT NULL CHECK (day_of_week BETWEEN 0 AND 6),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (spa_id, therapist_id, day_of_week)
);
CREATE INDEX therapist_shift_assignments_therapist_idx
  ON therapist_shift_assignments (spa_id, therapist_id, day_of_week);

COMMENT ON TABLE shifts IS 'Reusable daily work-time window for a spa.';
COMMENT ON COLUMN shifts.start_time IS 'Local shift start time; shifts do not cross midnight.';
COMMENT ON COLUMN shifts.end_time IS 'Local shift end time; must be later than start_time.';
COMMENT ON TABLE therapist_shift_assignments IS 'Weekly therapist roster; one shift per weekday. Monday=0 through Sunday=6.';
COMMENT ON COLUMN therapist_shift_assignments.day_of_week IS 'ISO weekday number: Monday 0, Tuesday 1, ..., Sunday 6.';

COMMENT ON COLUMN shifts.id IS 'Identity.';
COMMENT ON COLUMN shifts.spa_id IS 'Owning spa; shift templates are tenant-scoped.';
COMMENT ON COLUMN shifts.name IS 'Display name of the reusable work-time window.';
COMMENT ON COLUMN shifts.is_active IS 'Inactive shifts cannot be assigned to therapists.';
COMMENT ON COLUMN shifts.created_at IS 'When the shift template was created.';
COMMENT ON COLUMN therapist_shift_assignments.id IS 'Identity.';
COMMENT ON COLUMN therapist_shift_assignments.spa_id IS 'Owning spa; must match the therapist and shift.';
COMMENT ON COLUMN therapist_shift_assignments.therapist_id IS 'Therapist assigned to this weekly shift.';
COMMENT ON COLUMN therapist_shift_assignments.shift_id IS 'Reusable shift template assigned for this weekday.';
COMMENT ON COLUMN therapist_shift_assignments.created_at IS 'When the weekly assignment was created.';

-- ======== 008_plan_topups.sql ========
-- Top-ups add to an existing prepaid plan; each one is kept so sales reports count it in its own period.
CREATE TABLE plan_topups (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  plan_id BIGINT NOT NULL REFERENCES customer_plans(id),
  spa_id BIGINT NOT NULL REFERENCES spas(id),
  amount NUMERIC(12,2) NOT NULL CHECK (amount > 0),
  note TEXT,
  created_by BIGINT REFERENCES users(id),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX plan_topups_spa_time_idx ON plan_topups (spa_id, created_at);
CREATE INDEX plan_topups_plan_idx ON plan_topups (plan_id, created_at);
COMMENT ON TABLE plan_topups IS 'Amounts added to an existing prepaid plan after it was sold.';
COMMENT ON COLUMN plan_topups.id IS 'Identity.';
COMMENT ON COLUMN plan_topups.plan_id IS 'Plan that was topped up.';
COMMENT ON COLUMN plan_topups.spa_id IS 'Owning spa; same as the plan.';
COMMENT ON COLUMN plan_topups.amount IS 'Amount added, in the plan unit (hours or rupees).';
COMMENT ON COLUMN plan_topups.note IS 'Optional note, e.g. payment details.';
COMMENT ON COLUMN plan_topups.created_by IS 'Login that added the top-up.';
COMMENT ON COLUMN plan_topups.created_at IS 'When the top-up was added.';

-- ======== 009_plan_price_paid.sql ========
-- What the customer actually paid for a plan or a top-up, so plan sales count as revenue.
ALTER TABLE customer_plans ADD COLUMN IF NOT EXISTS price_paid NUMERIC(12,2) CHECK (price_paid >= 0);
ALTER TABLE plan_topups ADD COLUMN IF NOT EXISTS price_paid NUMERIC(12,2) CHECK (price_paid >= 0);
-- rupee plans: paid what was loaded; hours plans sold before this have no known price (counted as 0)
UPDATE customer_plans p SET price_paid = p.purchased_amount
       - COALESCE((SELECT SUM(x.amount) FROM plan_topups x WHERE x.plan_id = p.id), 0)
 WHERE p.price_paid IS NULL AND p.plan_type = 'rupees';
UPDATE plan_topups x SET price_paid = x.amount FROM customer_plans p
 WHERE p.id = x.plan_id AND x.price_paid IS NULL AND p.plan_type = 'rupees';
COMMENT ON COLUMN customer_plans.price_paid IS 'Money received when the plan was sold (INR); counted as revenue on the sale date.';
COMMENT ON COLUMN plan_topups.price_paid IS 'Money received for this top-up (INR); counted as revenue on the top-up date.';

-- ======== 010_expenses.sql ========
-- Spa running costs: regular monthly ones (rent, electricity, salaries outside payroll...) and one-off spends.
CREATE TABLE recurring_expenses (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  spa_id BIGINT NOT NULL REFERENCES spas(id),
  name TEXT NOT NULL CHECK (length(btrim(name)) > 0),
  category TEXT NOT NULL DEFAULT 'Other',
  amount NUMERIC(12,2) NOT NULL CHECK (amount > 0),
  day_of_month SMALLINT NOT NULL DEFAULT 1 CHECK (day_of_month BETWEEN 1 AND 28),
  starts_on DATE NOT NULL,
  ends_on DATE,
  notes TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK (ends_on IS NULL OR ends_on >= starts_on)
);
CREATE INDEX recurring_expenses_spa_idx ON recurring_expenses (spa_id, starts_on);

CREATE TABLE expenses (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  spa_id BIGINT NOT NULL REFERENCES spas(id),
  on_date DATE NOT NULL,
  category TEXT NOT NULL DEFAULT 'Other',
  amount NUMERIC(12,2) NOT NULL CHECK (amount > 0),
  note TEXT,
  created_by BIGINT REFERENCES users(id),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX expenses_spa_date_idx ON expenses (spa_id, on_date);

COMMENT ON TABLE recurring_expenses IS 'A cost charged every month on a fixed day (rent, electricity, internet...), counted in each month it is active.';
COMMENT ON COLUMN recurring_expenses.id IS 'Identity.';
COMMENT ON COLUMN recurring_expenses.spa_id IS 'Owning spa.';
COMMENT ON COLUMN recurring_expenses.name IS 'What the cost is, e.g. Shop rent.';
COMMENT ON COLUMN recurring_expenses.category IS 'Grouping for reports, e.g. Rent, Utilities, Supplies.';
COMMENT ON COLUMN recurring_expenses.amount IS 'Monthly amount in INR.';
COMMENT ON COLUMN recurring_expenses.day_of_month IS 'Day (1-28) it falls due each month.';
COMMENT ON COLUMN recurring_expenses.starts_on IS 'First date it applies; months before are not charged.';
COMMENT ON COLUMN recurring_expenses.ends_on IS 'Last date it applies; NULL = ongoing.';
COMMENT ON COLUMN recurring_expenses.notes IS 'Optional notes.';
COMMENT ON COLUMN recurring_expenses.created_at IS 'When it was added.';
COMMENT ON TABLE expenses IS 'One-off spa costs on a given date.';
COMMENT ON COLUMN expenses.id IS 'Identity.';
COMMENT ON COLUMN expenses.spa_id IS 'Owning spa.';
COMMENT ON COLUMN expenses.on_date IS 'Date the money was spent.';
COMMENT ON COLUMN expenses.category IS 'Grouping for reports, e.g. Supplies, Repairs, Marketing.';
COMMENT ON COLUMN expenses.amount IS 'Amount in INR.';
COMMENT ON COLUMN expenses.note IS 'What it was for.';
COMMENT ON COLUMN expenses.created_by IS 'Login that recorded it.';
COMMENT ON COLUMN expenses.created_at IS 'When it was recorded.';

-- ======== 011_appointment_payments.sql ========
-- Payments received against appointments and immutable refund records.
CREATE TABLE payments (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  spa_id BIGINT NOT NULL REFERENCES spas(id),
  appointment_id BIGINT NOT NULL REFERENCES appointments(id),
  customer_id BIGINT NOT NULL REFERENCES customers(id),
  amount NUMERIC(12,2) NOT NULL CHECK (amount > 0),
  method TEXT NOT NULL CHECK (method IN ('cash','upi','card','bank_transfer','other')),
  reference TEXT,
  note TEXT,
  received_by BIGINT REFERENCES users(id),
  received_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX payments_spa_received_idx ON payments (spa_id, received_at DESC);
CREATE INDEX payments_appointment_idx ON payments (spa_id, appointment_id, received_at);

CREATE TABLE payment_refunds (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  spa_id BIGINT NOT NULL REFERENCES spas(id),
  payment_id BIGINT NOT NULL REFERENCES payments(id),
  amount NUMERIC(12,2) NOT NULL CHECK (amount > 0),
  reason TEXT,
  refunded_by BIGINT REFERENCES users(id),
  refunded_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX payment_refunds_payment_idx ON payment_refunds (spa_id, payment_id, refunded_at);

COMMENT ON TABLE payments IS 'Amounts collected from customers against appointments; multiple partial payments are allowed.';
COMMENT ON COLUMN payments.id IS 'Identity and receipt number source.';
COMMENT ON COLUMN payments.spa_id IS 'Owning spa for tenant isolation.';
COMMENT ON COLUMN payments.appointment_id IS 'Appointment this payment settles.';
COMMENT ON COLUMN payments.customer_id IS 'Customer from whom payment was received.';
COMMENT ON COLUMN payments.amount IS 'Gross amount received in INR.';
COMMENT ON COLUMN payments.method IS 'Collection method: cash, UPI, card, bank transfer, or other.';
COMMENT ON COLUMN payments.reference IS 'Optional transaction reference, e.g. UPI reference or card slip.';
COMMENT ON COLUMN payments.note IS 'Optional note entered by the cashier.';
COMMENT ON COLUMN payments.received_by IS 'Login that recorded the payment.';
COMMENT ON COLUMN payments.received_at IS 'Local settlement timestamp for daily collection reports.';
COMMENT ON COLUMN payments.created_at IS 'When the payment record was created.';
COMMENT ON TABLE payment_refunds IS 'Immutable partial or full refunds against recorded appointment payments.';
COMMENT ON COLUMN payment_refunds.id IS 'Identity.';
COMMENT ON COLUMN payment_refunds.spa_id IS 'Owning spa for tenant isolation.';
COMMENT ON COLUMN payment_refunds.payment_id IS 'Original payment being refunded.';
COMMENT ON COLUMN payment_refunds.amount IS 'Refunded amount in INR; cumulative refunds cannot exceed the payment.';
COMMENT ON COLUMN payment_refunds.reason IS 'Optional reason for the refund.';
COMMENT ON COLUMN payment_refunds.refunded_by IS 'Admin login that authorised the refund.';
COMMENT ON COLUMN payment_refunds.refunded_at IS 'When the refund was recorded.';

-- ======== 012_customer_payment_preference.sql ========
-- Optional preferred payment method shown as a default at checkout; transaction methods remain independent.
ALTER TABLE customers ADD COLUMN preferred_payment_method TEXT;
ALTER TABLE customers ADD CONSTRAINT customers_preferred_payment_method_check
  CHECK (preferred_payment_method IS NULL OR preferred_payment_method IN ('cash','upi','card','bank_transfer','other'));

COMMENT ON COLUMN customers.preferred_payment_method IS 'Optional default payment method preference; each payment records its actual method independently.';

-- ======== 013_plan_paid_status.sql ========
-- A plan or top-up can be sold on credit: paid_at NULL = payment pending; revenue counts it when it is paid.
ALTER TABLE customer_plans ADD COLUMN IF NOT EXISTS paid_at TIMESTAMPTZ;
ALTER TABLE plan_topups ADD COLUMN IF NOT EXISTS paid_at TIMESTAMPTZ;
UPDATE customer_plans SET paid_at = created_at WHERE paid_at IS NULL;
UPDATE plan_topups SET paid_at = created_at WHERE paid_at IS NULL;
COMMENT ON COLUMN customer_plans.paid_at IS 'When the plan cost was received; NULL = payment pending. Plan sales count on this date.';
COMMENT ON COLUMN plan_topups.paid_at IS 'When the top-up cost was received; NULL = payment pending. Plan sales count on this date.';

-- ======== 014_spa_logo.sql ========
-- Each spa owns its own optional brand logo. The UI stores a normalized image data URL.
ALTER TABLE spas ADD COLUMN logo_data_url TEXT;
COMMENT ON COLUMN spas.logo_data_url IS 'Optional PNG, JPEG or WebP logo data URL for this spa; independent of other spas.';

-- ======== 015_spa_receipt_address.sql ========
-- Optional business address printed beneath the spa logo/name on customer receipts.
ALTER TABLE spas ADD COLUMN address TEXT;
COMMENT ON COLUMN spas.address IS 'Optional business address displayed on customer receipts.';

-- ======== 016_plan_packages.sql ========
-- Plan packages: the plans a spa sells, at fixed prices, set up by an admin. Staff assign a package to a customer.
CREATE TABLE plan_packages (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  spa_id BIGINT NOT NULL REFERENCES spas(id),
  name TEXT NOT NULL CHECK (length(btrim(name)) > 0),
  plan_type TEXT NOT NULL CHECK (plan_type IN ('hours', 'rupees')),
  amount NUMERIC(12,2) NOT NULL CHECK (amount > 0),
  price NUMERIC(12,2) NOT NULL CHECK (price >= 0),
  validity_days INT CHECK (validity_days > 0),
  is_active BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX plan_packages_spa_name_key ON plan_packages (spa_id, lower(name));
ALTER TABLE customer_plans ADD COLUMN IF NOT EXISTS package_id BIGINT REFERENCES plan_packages(id);
COMMENT ON TABLE plan_packages IS 'Plans a spa sells at a fixed price; staff assign them to customers.';
COMMENT ON COLUMN plan_packages.id IS 'Identity.';
COMMENT ON COLUMN plan_packages.spa_id IS 'Owning spa.';
COMMENT ON COLUMN plan_packages.name IS 'Package name, e.g. 10 Hours Gold.';
COMMENT ON COLUMN plan_packages.plan_type IS 'hours or rupees, like customer_plans.plan_type.';
COMMENT ON COLUMN plan_packages.amount IS 'Hours or rupees the customer gets.';
COMMENT ON COLUMN plan_packages.price IS 'What the customer pays (INR).';
COMMENT ON COLUMN plan_packages.validity_days IS 'Days the plan stays valid after it is assigned; NULL = no expiry.';
COMMENT ON COLUMN plan_packages.is_active IS 'Inactive packages cannot be assigned; plans already sold are unaffected.';
COMMENT ON COLUMN plan_packages.created_at IS 'When the package was created.';
COMMENT ON COLUMN customer_plans.package_id IS 'Package the plan was assigned from; NULL = custom plan made by an admin.';

-- ======== 017_payment_methods.sql ========
-- Every money movement records how it was paid: plan sales, top-ups and expenses as well as appointment payments.
ALTER TABLE customer_plans ADD COLUMN IF NOT EXISTS payment_method TEXT
  CHECK (payment_method IN ('cash','upi','card','bank_transfer','other'));
ALTER TABLE plan_topups ADD COLUMN IF NOT EXISTS payment_method TEXT
  CHECK (payment_method IN ('cash','upi','card','bank_transfer','other'));
ALTER TABLE expenses ADD COLUMN IF NOT EXISTS payment_method TEXT
  CHECK (payment_method IN ('cash','upi','card','bank_transfer','other'));
-- records made before this did not say; mark them 'other'
UPDATE customer_plans SET payment_method='other' WHERE payment_method IS NULL AND paid_at IS NOT NULL;
UPDATE plan_topups SET payment_method='other' WHERE payment_method IS NULL AND paid_at IS NOT NULL;
UPDATE expenses SET payment_method='other' WHERE payment_method IS NULL;
COMMENT ON COLUMN customer_plans.payment_method IS 'How the plan cost was paid (cash, upi, card, bank_transfer, other); NULL while pending.';
COMMENT ON COLUMN plan_topups.payment_method IS 'How the top-up was paid (cash, upi, card, bank_transfer, other); NULL while pending.';
COMMENT ON COLUMN expenses.payment_method IS 'How the expense was paid (cash, upi, card, bank_transfer, other).';

-- ======== 018_audit_log.sql ========
-- Who changed what: one row per successful change (create, edit, delete, status, refund, payment, login...).
CREATE TABLE audit_log (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  at TIMESTAMPTZ NOT NULL DEFAULT now(),
  spa_id BIGINT REFERENCES spas(id),
  user_id BIGINT REFERENCES users(id),
  username TEXT,
  role TEXT,
  action TEXT NOT NULL,
  method TEXT NOT NULL,
  path TEXT NOT NULL,
  status SMALLINT NOT NULL,
  details JSONB,
  ip TEXT
);
CREATE INDEX audit_log_spa_at_idx ON audit_log (spa_id, at DESC);
CREATE INDEX audit_log_user_at_idx ON audit_log (user_id, at DESC);
COMMENT ON TABLE audit_log IS 'Append-only record of every successful change made through the API; never edited or deleted by the app.';
COMMENT ON COLUMN audit_log.id IS 'Identity.';
COMMENT ON COLUMN audit_log.at IS 'When the change happened.';
COMMENT ON COLUMN audit_log.spa_id IS 'Spa the change was made in (NULL for superadmin-wide actions).';
COMMENT ON COLUMN audit_log.user_id IS 'Login that made the change.';
COMMENT ON COLUMN audit_log.username IS 'Username at the time, kept even if the login is renamed.';
COMMENT ON COLUMN audit_log.role IS 'Role at the time (superadmin, admin, staff).';
COMMENT ON COLUMN audit_log.action IS 'Readable action, e.g. "Refund payment", "Edit service".';
COMMENT ON COLUMN audit_log.method IS 'HTTP method (POST, PUT, PATCH, DELETE).';
COMMENT ON COLUMN audit_log.path IS 'API path, with record ids.';
COMMENT ON COLUMN audit_log.status IS 'HTTP status returned.';
COMMENT ON COLUMN audit_log.details IS 'Request body with passwords and tokens removed.';
COMMENT ON COLUMN audit_log.ip IS 'Client address as seen by the API.';

-- ======== 019_therapist_absences.sql ========
-- Therapist leave: only absences are recorded; days present = scheduled shift days minus absences.
CREATE TABLE therapist_absences (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  spa_id BIGINT NOT NULL REFERENCES spas(id),
  therapist_id BIGINT NOT NULL REFERENCES therapists(id),
  on_date DATE NOT NULL,
  kind TEXT NOT NULL DEFAULT 'leave' CHECK (kind IN ('leave','sick','absent','holiday')),
  half_day BOOLEAN NOT NULL DEFAULT false,
  note TEXT,
  created_by BIGINT REFERENCES users(id),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (therapist_id, on_date)
);
CREATE INDEX therapist_absences_spa_date_idx ON therapist_absences (spa_id, on_date);
COMMENT ON TABLE therapist_absences IS 'Days a therapist was away; attendance counts scheduled shift days minus these.';
COMMENT ON COLUMN therapist_absences.id IS 'Identity.';
COMMENT ON COLUMN therapist_absences.spa_id IS 'Owning spa.';
COMMENT ON COLUMN therapist_absences.therapist_id IS 'Therapist who was away.';
COMMENT ON COLUMN therapist_absences.on_date IS 'The day away.';
COMMENT ON COLUMN therapist_absences.kind IS 'leave, sick, absent (no notice) or holiday.';
COMMENT ON COLUMN therapist_absences.half_day IS 'Away for half the day (counts 0.5).';
COMMENT ON COLUMN therapist_absences.note IS 'Optional reason.';
COMMENT ON COLUMN therapist_absences.created_by IS 'Login that recorded it.';
COMMENT ON COLUMN therapist_absences.created_at IS 'When it was recorded.';

